"""Write evidence-backed, manually adjudicated batch03 reports and schema rows."""
import csv,json,hashlib
from pathlib import Path
B=Path(__file__).resolve().parent;ROOT=B.parent
queue=list(csv.DictReader((B/'queue.csv').open(newline='',encoding='utf-8')))
cov={x['sample_id']:x for x in json.loads((B/'lead-gaia-covariance.json').read_text())}
current={x['sample_id']:x for x in json.loads((B/'lead-current-sectors.json').read_text())}
manual={
'T021':dict(v='REFUTED',p='',pe='',epoch='',depth='',limitations='Retained windows are dominated by gross sector trends and discontinuities; no eclipse clock can be measured.',next='If an independent future light curve is obtained, search it afresh for isolated events.',evidence='The s65 flagged deficit sits on a nearly monotonic ~90% sector-scale decline. The s99 flags are opposing 259 and 245 ppt steps across 0.25 d gaps, and s93 falls through a gap on a sloping baseline. These shapes change sign and amplitude across sectors and do not furnish repeatable same-kind eclipses.',alt='Raw morphology and measured gap steps positively identify the selected windows as extraction/baseline artifacts; another pipeline is unnecessary to refute those windows.'),
'T022':dict(v='REFUTED',p='',pe='',epoch='',depth='',limitations='One selected window; no independent astrophysical eclipse remains after raw-shape inspection.',next='Revisit only if a future light curve shows an isolated return to baseline at a consistent phase.',evidence='The s85 screen time 3623.76 is immediately after a data gap; flux then rises monotonically by roughly 50 ppt over the next day without an eclipse egress. The s18 and s58 raw curves show no corresponding dip. This is a gap-edge/baseline feature, not a timed eclipse.',alt='The opposite post-gap trend in the same raw window is positive contrary evidence to an isolated eclipse.'),
'T023':dict(v='REFUTED',p='',pe='',epoch='',depth='',limitations='The s101 flagged ingress is truncated; repeated sector-edge resets explain similar later shapes.',next='A future isolated event away from a data gap would warrant a new review.',evidence='s101 falls toward BTJD 4113.2, ends at a 1.13 d gap, then resumes 13.9 ppt higher. s102 and s103 show the same falling-into-gap/rising-after-gap pattern around 4139 and 4165 despite no same-kind eclipse timing. The recurring downlink-edge shape is positive instrumental evidence.',alt='QLP alternate flux follows the same-photon data and cannot turn these gap-terminated segments into a measured clock.'),
'T024':dict(v='PLAUSIBLE',p='',pe='',epoch='',depth='6',limitations='The s26 ~6 ppt dip near 2033.5 is shallow on a changing baseline; a second nearby screen dip does not establish recurrence. KSPSAP suppresses it, which alone is not a refutation.',next='Acquire an independent event or useful later-sector coverage and a pixel-level source check.',evidence='s26 raw SAP contains a shallow trough around 2033.5 with apparent recovery, while another much weaker depression about one day earlier does not match a 39.14 d same-kind clock. Eight sectors are already cached, through s74; the current footprint query adds no sector beyond that cached coverage. This leaves eclipse interpretation insecure, with no measured period.',alt='In the same s26 samples, the raw SAP core deficit is ~7.1 ppt and QLP KSPSAP is about -0.3 ppt. Detrending suppression is recorded as a limitation rather than artifact proof.'),
'T025':dict(v='PLAUSIBLE',p='',pe='',epoch='',depth='8',limitations='s79 has an ingress and flat bottom but egress is in a data gap. Other selected troughs often end at downlink gaps and do not form one Gaia-period clock. s77 and s86 current cutouts have negligible target flux, so neither supplies a recurrence null.',next='Obtain a clean same-kind repeat and a higher-resolution source check.',evidence='The s79 raw SAP trough near 3464.7 reaches ~8 ppt with a relatively level bottom, then a 0.25 d gap and +10.3 ppt step hide its egress. s40, s53 and s83 show similar gap-ended broad declines with 10–20 ppt post-gap steps; s80 has a different step. These cannot be counted as same-kind recurrences. A single real s79 event remains possible.',alt='Terra independently extracted s79 TESScut target-centered 3x3 flux: bright target is present, but a broad decline and gap/step dominate; a local-window statistic is only 1.11 ppt and depends on the baseline. s77 has 0.00947 net counts; lead s86 has 0.53 counts (1.4% of positive cutout flux). Neither is a sensitive null. See helper-audit.txt and helper-pixels.json.'),
'T026':dict(v='PROBABLE',p='58.157443',pe='0.000349',epoch='1703.35043',depth='5.8',limitations='Four same-kind eclipses and a tested clock, but the Gaia neighbor 6.66 arcsec away at G 12.36 could produce the diluted loss. TESScut s48 difference imaging places the deficit on their unresolved blend.',next='Resolve target versus the 6.66 arcsec neighbor with high-resolution in-eclipse imaging or spectroscopy.',evidence='Sharp raw SAP dips occur in s14 at 1703.34705, s21 at 1877.82516, s48 at 2633.87057 and s74 at 3331.75814. Their cycle counts 0,3,16,28 yield P=58.157443 d with residuals at most 0.0034 d. Local depths are 5.2–6.6 ppt and durations 0.13–0.15 d. The s48 event was absent from retained flags and s74 from the initial ranking; both were recovered at the measured clock.',alt='QLP KSPSAP shows s14/s21/s48 dips of ~4.0/4.9/4.3 ppt in the same photons. Terra independently extracted a 2.68 ppt s48 deficit from a TESScut 3x3 aperture; its difference image is on the target/neighbor blend, 0.317 TESS pixel apart, and cannot distinguish them. These are alternative reductions of the same photons, not additional observing occasions. Current TESS footprint has no newer sector than s75.'),
'T027':dict(v='REFUTED',p='',pe='',epoch='',depth='',limitations='The largest sector81 dips are on orbital-gap boundaries; no secure isolated eclipse is timed.',next='Reassess if an independent, fully observed eclipse-shaped event appears.',evidence='s81 flux slides downward for days into gaps near 3518 and 3531, 13.4 d apart; the gaps are 1.49 and 0.82 d, followed by +58 and +38 ppt resets. s73 has a similar disturbed region. The two s81 structures track TESS downlink spacing, not the Gaia 53.46 d same-kind orbit.',alt='Gap-resets and pre-gap long slopes are positive counterevidence to treating the two window statistics as eclipses.'),
'T028':dict(v='REFUTED',p='',pe='',epoch='',depth='',limitations='Strong variable flux is present, but no isolated eclipse clock follows the 33.73 d Gaia orbit.',next='Classify the smooth stellar/field variability separately if useful; search future data for isolated eclipses only on new evidence.',evidence='The s34/s61/s88 selected V shapes sit against continuous multi-day waves; each encounters a nearby gap and +16–23 ppt post-gap step. Their spacings 734.8 and 714.5 d cannot both follow a 33.73 d same-kind clock. New s108 TESScut shows strong continuous waves in a target-containing 3x3 aperture over 10,999 quality-zero cadences, corroborating non-eclipse variability.',alt='s108 target 3x3 holds 15,236 counts (32% of positive cutout flux). Older s7 cutout has near-zero target flux and is explicitly not used as a null.'),
'T029':dict(v='REFUTED',p='',pe='',epoch='',depth='',limitations='The raw dips belong to a continuous quasi-periodic wave, with no eclipse-like isolated floor or Gaia-period clock.',next='Model the non-eclipse variability if astrophysically interesting.',evidence='Across s9/10/36/63/90/99/100, repeated rounded troughs alternate with broad humps on about a 6.5 d scale. s63 alone has four troughs roughly 3.2 d apart; several selected flags are successive wave minima. The flux changes continuously before and after each minimum rather than entering and exiting an isolated eclipse, and Gaia P=25.95 d is not established by event timing.',alt='The persistent smooth waveform across multiple sectors is a positive alternative explanation for the detector windows.'),
'T030':dict(v='REFUTED',p='',pe='',epoch='',depth='',limitations='All retained windows are steep trends or baseline discontinuities; no repeatable eclipse center.',next='Reopen only for an isolated new event supported by raw and spatial data.',evidence='s65 has a >300 ppt recovery along a large slope; s99 windows sit on long rising/falling trends separated by gaps, including an ~11 ppt step; s102 shows a nearly monotonic rise and a ~20 ppt local reset. Fitted trapezoid centers move with arbitrary local span and do not form an orbital clock.',alt='The observed long slopes and discontinuities are positive instrumental/baseline explanations for the selected flags.'),
}
status={r['sample_id']:r for r in csv.DictReader((ROOT/'shared-catalogues/TARGET-STATUS.csv').open(newline='',encoding='utf-8'))}
fields='sample_id,tic,sample_stratum,physical_verdict,full_review_completion,novelty_status,period_days,period_error_days,primary_epoch_btjd,depth_ppt,limitations,next_check,report'.split(',')
rows=[]
for r in queue:
    sid=r['sample_id'];tic=r['tic'];m=manual[sid];num=json.loads((B/tic/'lead-numeric.json').read_text());c=cov[sid];p=ROOT/'source-packets'/tic/'sources.json';sha=hashlib.sha256(p.read_bytes()).hexdigest()
    neighbors=json.loads((ROOT/'shared-catalogues/gaia-neighbors.json').read_text())['targets'][sid];close=[n for n in neighbors[1:] if float(n['separation_arcsec'])<10]
    close_text='; '.join(f"{float(n['separation_arcsec']):.2f} arcsec G={float(n['phot_g_mean_mag']):.2f}" for n in close) or 'none within 10 arcsec'
    footprint=current[sid];fs=[x['sectorName'] for x in footprint.get('response',{}).get('results',[])] if 'response' in footprint else []
    txt=f"# {sid} — TIC {tic}\n\n**Physical verdict:** {m['v']}. **Full bounded review:** COMPLETE. **Catalogue novelty:** UNKNOWN; shared catalogue checks lack four VizieR gates (VSX, ASAS-SN, Kostov 2025 tables 3 and 4) after failed positive controls. This is not a negative catalogue match.\n\n## Raw event and timing evidence\n\n{m['evidence']}\n\nMeasured eclipse period: {m['p']+' ± '+m['pe']+' d' if m['p'] else 'none supported'}. Epoch BTJD: {m['epoch'] or 'none supported'}. Depth: {m['depth']+' ppt' if m['depth'] else 'none supported'}. Screening times in the source packet are not measured centers. See [numeric review](lead-numeric.json), [raw panels](lead-raw-01.png), [sector panels](lead-sector-01.png), and batch [gap evidence](../lead-gap-evidence.json).\n\n## Attribution, reduction and orbit\n\nGaia DR3 {r['gaia_dr3']} has a spectroscopic orbit P={float(r['gaia_period_days']):.6f} d. At the evaluated event/screen epoch, the closest edge-on conjunction offset is {c['closest']['offset_days']:.3f} d, with a {c['closest']['linear_sigma_days']:.3f} d linear Gaia-covariance uncertainty. This geometry comparison is supportive only if the raw feature is an eclipse. Gaia neighbors inside 10 arcsec: {close_text}. Neighbor flux ratios alone cannot assign a source.\n\n{m['alt']}\n\nThe MAST Tesscut footprint query lists {len(fs)} sectors, latest {max((int(s[6:10]) for s in fs),default=0)}. Its response is in [current-sector receipt](../lead-current-sectors.json).\n\n## Limits and next test\n\n{m['limitations']} {m['next']}\n\nSource packet SHA-256: `{sha}`. Every QLP FITS read by the numeric script was checked against its bulk packet hash; individual source paths and hashes are in `lead-numeric.json`. The shared Gaia neighbor and NSS catalogues were reused without new catalogue queries.\n"
    if sid=='T026':txt=txt.replace('See [numeric review]', 'See [four-event timing](lead-timing.json), [tested alias windows](../lead-t026-alias.json), [numeric review]')+'\nThe full-window alias checks reject 87.237 d (two cycles), 43.618 d (four cycles), 34.895 d (five cycles), 29.079 d (P/2) and 19.386 d (P/3) through cadence-complete raw nulls. The 58.157 d fit uses conservative timing-error floors rather than formal trapezoid errors alone. A 6.66 arcsec G=12.36 neighbor is capable: its Gaia-G flux ratio is ~0.403, implying only ~2% intrinsic eclipse depth for the observed ~5.8 ppt blended loss. See [helper audit](../helper-audit.txt), [difference image](helper-pixels-s48.png) and [numeric pixels](../helper-pixels.json).\n'
    if sid=='T025':txt+='\nThe s86 cutout and extraction receipt are [here](lead-cutout-s86.png) and [here](../lead-t025-cutout.json); s77 and s79 helper diagnostics are [here](helper-pixels-s77.png), [here](helper-pixels-s79.png), with [numeric pixels](../helper-pixels.json).\n'
    if sid=='T028':txt+='\nThe s108 cutout diagnostic is [here](lead-cutout-s108.png), with [numeric receipt](../lead-t028-cutout.json).\n'
    (B/tic/'REPORT.md').write_text(txt,encoding='utf-8')
    rows.append(dict(sample_id=sid,tic=tic,sample_stratum=r['sample_stratum'],physical_verdict=m['v'],full_review_completion='COMPLETE',novelty_status='UNKNOWN',period_days=m['p'],period_error_days=m['pe'],primary_epoch_btjd=m['epoch'],depth_ppt=m['depth'],limitations=m['limitations'],next_check=m['next'],report=str(B/tic/'REPORT.md')))
with (B/'RESULTS.csv').open('w',newline='',encoding='utf-8') as f:
    w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
print([(r['sample_id'],r['physical_verdict']) for r in rows])
